/**
 * Get wishes for a specific occasion.
 * @param {string} occasionId
 * @returns {Array}
 */
function getWishesForOccasion(occasionId) {
  return WISHES[occasionId] || GENERIC_WISHES;
}

/**
 * Filter wishes by category.
 * @param {string} occasionId
 * @param {string} category - 'all' or specific category
 * @returns {Array}
 */
function filterWishes(occasionId, category) {
  const wishes = getWishesForOccasion(occasionId);
  if (category === 'all') return wishes;
  return wishes.filter(w => w.category === category);
}

/**
 * Get a single wish by its occasion and id.
 * @param {string} occasionId
 * @param {string} wishId
 * @returns {object|null}
 */
function getWishById(occasionId, wishId) {
  const wishes = getWishesForOccasion(occasionId);
  return wishes.find(w => w.id === wishId) || null;
}
